static int failures=0;static long fail_after=-1;
void *operator new(size_t n){if(fail_after==0)throw std::bad_alloc();if(fail_after>0)--fail_after;if(auto p=malloc(n?n:1))return p;throw std::bad_alloc();}
void *operator new[](size_t n){return ::operator new(n);}void operator delete(void *p) noexcept{free(p);}void operator delete[](void *p) noexcept{free(p);}void operator delete(void *p,size_t) noexcept{free(p);}void operator delete[](void *p,size_t) noexcept{free(p);}
#define CHECK(x) do{if(!(x)){if(failures<20)std::cerr<<"FAIL "<<__LINE__<<": " #x " / "<<error<<'\n';++failures;}}while(0)
using namespace studio;namespace fs=std::filesystem;
static std::string read(const fs::path &p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
static std::string state(const SceneState &s){std::ostringstream o;o<<s.width<<'|'<<s.height<<'|'<<s.origin_x<<'|'<<s.origin_y<<'|'<<s.floor<<'|'<<s.onion<<s.loop<<s.ghost_facing<<'|'<<s.convention<<'|'<<s.tick_hz;for(int c:s.background)o<<'|'<<c;for(auto &a:s.assets)o<<a.path<<'|'<<a.absolute_path<<'|'<<a.digest<<'|'<<a.runtime_doc<<'\n';for(auto &l:s.lanes){o<<l.name<<'|'<<l.id<<'|'<<l.x<<'|'<<l.y<<'|'<<l.delay<<'|'<<l.alpha<<'|'<<l.visible<<l.loop<<l.hold_end<<l.flip_x<<'|'<<l.stop_tick<<'|'<<l.trigger_lane<<'|'<<l.trigger_frame<<'|'<<l.magnification<<'\n';for(auto &f:l.frames){o<<f.name<<'|'<<f.id<<'|'<<f.ticks<<'|'<<f.x<<'|'<<f.y<<'|'<<f.z<<'|'<<f.flip_x<<f.flip_y<<'|'<<f.visible_from<<'|'<<f.visible_until<<'|'<<f.independent_timing<<'|'<<f.vx<<'|'<<f.vy<<'|'<<f.cap_x<<'|'<<f.cap_y<<'|'<<f.dual<<'|'<<f.dual_x<<'|'<<f.dual_y<<'|'<<f.dual_z<<'\n';for(auto &r:f.pieces)o<<r.asset<<'|'<<r.index<<'|'<<r.key<<'|'<<r.name<<'|'<<r.runtime_id<<'\n';}}return o.str();}
static SceneState fixture(const Artwork &a,const Artwork &b){SceneState s;s.loop=false;s.origin_y=190;s.assets={{a.path(),a.path(),{},1},{b.path(),b.path(),{},2}};SceneLane l;l.id=10;l.name="Source";l.x=-20;l.delay=2;l.alpha=125;l.loop=false;l.flip_x=true;l.magnification=3;l.stop_tick=30;
    for(int i=0;i<3;++i){SceneFrame f;f.id=11+i;f.name="Frame "+std::to_string(i);f.ticks=4+i;f.x=7+i;f.y=-3;f.z=i;f.vx=2;f.vy=-1;f.cap_x=6;f.cap_y=4;f.dual=true;f.dual_x=-12;f.dual_y=5;f.dual_z=-2;f.flip_x=i!=0;f.flip_y=i==0;if(i==1){f.visible_from=3;f.visible_until=9;}if(i==2)f.independent_timing=true;f.pieces={scene_sprite_reference(a,0,i),scene_sprite_reference(b,1,i+1)};l.frames.push_back(f);}SceneLane dst;dst.id=20;dst.name="Destination";dst.x=40;dst.delay=7;dst.loop=false;dst.magnification=2;for(int i=0;i<2;++i){SceneFrame f;f.id=21+i;f.name="Destination "+std::to_string(i);f.pieces={scene_sprite_reference(b,1,i+4)};dst.frames.push_back(f);}SceneLane fx;fx.id=30;fx.name="Follower";fx.trigger_lane=10;fx.trigger_frame=12;fx.delay=2;SceneFrame f;f.id=31;f.name="FX";f.pieces={scene_sprite_reference(a,0,7)};fx.frames={f};s.lanes={l,dst,fx};return s;}
int main(){std::string error;auto parent=fs::temp_directory_path();auto root=parent/("studio-frame-transfer-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directory(root);auto a=Artwork::demo(),b=Artwork::demo();CHECK(a->save((root/"a.IMG").u8string(),error)&&b->save((root/"b.IMG").u8string(),error));auto ab=read(root/"a.IMG"),bb=read(root/"b.IMG");auto ag=a->generation(),bg=b->generation();auto source=[&](uint64_t id){return id==1?a.get():id==2?b.get():nullptr;};auto initial=fixture(*a,*b);SceneProject p(initial);auto file=root/"transfer.ISTUDIO";CHECK(p.save(file.u8string(),source,error));auto before=state(p.state);auto expected=p.state;
    CHECK(p.transfer_frames(10,{13,11},20,1,false,error)==1&&p.dirty());auto first=initial.lanes[0].frames[0],last=initial.lanes[0].frames[2];first.id=32;last.id=33;expected.lanes[1].frames.insert(expected.lanes[1].frames.begin()+1,{first,last});CHECK(state(p.state)==state(expected)&&p.state.lanes[2].trigger_lane==10&&p.state.lanes[2].trigger_frame==12);auto copied=state(p.state);p.undo();CHECK(state(p.state)==before&&!p.dirty()&&p.can_redo());p.redo();CHECK(state(p.state)==copied);p.undo();CHECK(p.transfer_frames(10,{11},20,2,false,error)==2&&p.state.lanes[1].frames[2].id==34);p.undo();
    CHECK(p.transfer_frames(10,{12},20,0,true,error)==0);expected=p.state;auto moved=state(p.state);CHECK(p.state.lanes[0].frames.size()==2&&p.state.lanes[0].frames[0].id==11&&p.state.lanes[0].frames[1].id==13&&p.state.lanes[1].frames[0].id==12&&p.state.lanes[2].trigger_lane==20&&scene_lane_start(p.state,2)==12);auto field_check=initial;field_check.assets=p.state.assets;auto frame=field_check.lanes[0].frames[1];field_check.lanes[0].frames.erase(field_check.lanes[0].frames.begin()+1);field_check.lanes[1].frames.insert(field_check.lanes[1].frames.begin(),frame);field_check.lanes[2].trigger_lane=20;CHECK(state(p.state)==state(field_check));
    CHECK(p.save(file.u8string(),source,error));auto saved=read(file);auto round=SceneProject::read(file.u8string(),error);std::vector<SceneIssue> issues;CHECK(round&&round->bind([&](int i,const SceneAsset &){return SceneBinding{i?2ull:1ull,i?b.get():a.get()};},issues));if(round){CHECK(round->save(file.u8string(),source,error)&&read(file)==saved);for(int tick:{0,2,7,10,12,20,50})CHECK(p.export_png((root/"before.png").u8string(),tick,source,error)&&round->export_png((root/"after.png").u8string(),tick,source,error)&&read(root/"before.png")==read(root/"after.png"));}p.undo();CHECK(state(p.state)==before&&p.can_redo());p.redo();CHECK(state(p.state)==moved);
    SceneProject same(initial,false);same.begin("Position");same.state.lanes[1].x++;same.commit();same.undo();CHECK(same.transfer_frames(10,{12},10,1,true,error)==1&&!same.can_undo()&&same.can_redo()&&!same.dirty());CHECK(same.transfer_frames(10,{12},10,2,true,error)==1&&same.can_redo());CHECK(same.transfer_frames(10,{11,12,13},10,3,true,error)==0&&same.can_redo());CHECK(same.transfer_frames(10,{13,11},10,3,true,error)==1);CHECK(same.state.lanes[0].frames[0].id==12&&same.state.lanes[0].frames[1].id==11&&same.state.lanes[0].frames[2].id==13);same.undo();CHECK(state(same.state)==state(initial));CHECK(same.transfer_frames(10,{11,12},10,3,false,error)==3&&same.state.lanes[0].frames.size()==5&&same.state.lanes[2].trigger_frame==12);
    auto reject=[&](uint64_t src,std::vector<uint64_t> ids,uint64_t dst,int at,bool move){SceneProject q(initial);q.begin("Position");q.state.lanes[1].x++;q.commit();q.undo();auto snap=state(q.state);CHECK(q.transfer_frames(src,ids,dst,at,move,error)==-1&&!error.empty()&&state(q.state)==snap&&!q.can_undo()&&q.can_redo()&&q.allocate_id()==32);};
    reject(0,{11},20,0,false);reject(10,{},20,0,false);reject(10,{11,11},20,0,false);reject(10,{0},20,0,false);reject(10,{21},20,0,false);reject(10,{11},99,0,false);reject(10,{11},20,-1,false);reject(10,{11},20,3,false);reject(10,{11,12,13},20,0,true);reject(30,{31},20,0,true);reject(10,{12},30,0,true); // Would make the follower depend on itself.
    SceneProject stale(initial);auto reviewed=stale.state;stale.state.lanes[1].x++;auto snap=state(stale.state);CHECK(stale.transfer_frames(10,{11},20,0,false,error,&reviewed)==-1&&state(stale.state)==snap&&!stale.can_undo());stale.state=reviewed;stale.begin("Pending");CHECK(stale.transfer_frames(10,{11},20,0,false,error)==-1&&stale.transaction_open());stale.cancel();
    auto full=initial;full.lanes.resize(2);auto repeated=full.lanes[1].frames[0];repeated.id=0;full.lanes[1].frames.assign(4096,repeated);SceneProject lane_limit(full);CHECK(lane_limit.transfer_frames(10,{11},20,0,false,error)==-1&&!lane_limit.can_undo());CHECK(lane_limit.transfer_frames(10,{11},20,0,true,error)==-1&&!lane_limit.can_undo());
    auto global=initial;for(auto &l:global.lanes){l.trigger_lane=l.trigger_frame=0;l.frames.assign(l.id==30?2192:3000,repeated);}SceneProject total(global);auto pick=total.state.lanes[0].frames[0].id;CHECK(total.transfer_frames(10,{pick},20,0,false,error)==-1&&!total.can_undo());auto pieces=initial;pieces.lanes.resize(2);auto ref=repeated.pieces[0];repeated.pieces.assign(32,ref);for(auto &l:pieces.lanes)l.frames.assign(1024,repeated);SceneProject refs(pieces);pick=refs.state.lanes[0].frames[0].id;CHECK(refs.transfer_frames(10,{pick},20,0,false,error)==-1&&!refs.can_undo());
    auto ids=initial;ids.lanes[0].frames[2].id=INT_MAX-1;SceneProject identity(ids);CHECK(identity.transfer_frames(10,{11,12},20,0,false,error)==-1&&!identity.can_undo());CHECK(identity.transfer_frames(10,{11},20,0,false,error)==0&&identity.state.lanes[1].frames[0].id==INT_MAX);CHECK(identity.transfer_frames(10,{11},20,0,true,error)==0); // Moving needs no new ID.
    for(bool move:{false,true}){int failed=0,succeeded=0;for(int n=0;n<1400;++n){SceneProject q(initial);q.begin("Position");q.state.lanes[1].x++;q.commit();q.undo();auto snapshot=state(q.state);int result=-1;fail_after=n;try{result=q.transfer_frames(10,{12},20,0,move,error);}catch(const std::bad_alloc &){}fail_after=-1;if(result<0){++failed;CHECK(state(q.state)==snapshot&&!q.can_undo()&&q.can_redo()&&q.allocate_id()==32);}else{++succeeded;CHECK(!q.can_redo());q.undo();CHECK(state(q.state)==snapshot);}}CHECK(failed>20&&succeeded>0);}
    CHECK(a->generation()==ag&&b->generation()==bg&&!a->dirty()&&!b->dirty()&&read(root/"a.IMG")==ab&&read(root/"b.IMG")==bb&&g_doc==nullptr);CHECK(fs::weakly_canonical(root).parent_path()==fs::weakly_canonical(parent));if(!failures&&fs::weakly_canonical(root).parent_path()==fs::weakly_canonical(parent))fs::remove_all(root);if(failures)std::cerr<<"Artifacts: "<<root<<'\n';std::cout<<"Frame transfer: "<<failures<<" failures\n";return failures?1:0;
}
